      if (landed) {
        const gx = Math.floor(cx(p) / TS), gy = Math.floor((bot(p) + 2) / TS), t = s.tk.find(q => q.ty === gy && gx >= q.tx && gx < q.tx + q.w);
        if (t && t.st === 0) { t.st = 1; t.t = 0; DD.float(t.tx * TS + t.w * 8, t.ty * TS - 18, 'SCRATCH', '#e8ecf4'); }
      }
