          ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.fillRect(X + 4, py + 2, W - 8, 2);
          if (t.st === 2) DD.text(t.res === 'dud' ? 'TRY AGAIN' : t.res === 'prize' ? 'FREE POPCORN' : '$1000', X + W / 2, py + 14, t.res === 'dud' ? '#6a6e7a' : '#10060a', 1, null, 'center');
          else { DD.text('IN THE MONEY', X + W / 2, py + 6, '#4a4e5c', 1, null, 'center'); ctx.fillStyle = '#9aa0b0'; for (let i = 0; i < 3; i++) ctx.fillRect(X + 10 + i * 17, py + 16, 14, 12); DD.text('$ $ $', X + W / 2, py + 20, '#e8ecf4', 1, null, 'center'); }
