      DD.art.motes(G, '#ffe6b0', 22, 0.4);
      ctx.save(); ctx.globalCompositeOperation = 'multiply'; ctx.fillStyle = 'rgb(255,' + Math.round(244 - 30 * t) + ',' + Math.round(236 - 50 * t) + ')'; ctx.fillRect(0, 0, VW, VH); ctx.restore();
      const vg = ctx.createRadialGradient(VW / 2, VH * 0.55, VH * 0.35, VW / 2, VH * 0.55, VW * 0.65); vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(10,2,8,0.4)'); ctx.fillStyle = vg; ctx.fillRect(0, 0, VW, VH);
